            <div class="sl-prose sl-markdown-viewer sl-my-4">
                <h1 id="introduction">Introduction</h1>
<p>API de calcul de dépréciation de véhicules avec gestion de quota et organisations.</p>
<aside>
    <strong>Base URL</strong>: <code>http://localhost:8000</code>
</aside>
<pre><code>This documentation aims to provide all the information you need to work with our API.

&lt;aside&gt;As you scroll, you'll see code examples for working with the API in different programming languages in the dark area to the right (or as part of the content on mobile).
You can switch the language used with the tabs at the top right (or from the nav menu at the top left on mobile).&lt;/aside&gt;</code></pre>

                <h1 id="authenticating-requests">Authenticating requests</h1>
<p>To authenticate requests, include an <strong><code>Authorization</code></strong> header with the value <strong><code>"Bearer {YOUR_AUTH_TOKEN}"</code></strong>.</p>
<p>All authenticated endpoints are marked with a <code>requires authentication</code> badge in the documentation below.</p>
<p>Pour obtenir un token, utilisez l'endpoint <code>POST /api/auth/login</code> avec vos identifiants. Le token sera retourné dans la réponse et devra être utilisé dans l'en-tête <code>Authorization: Bearer {token}</code> pour toutes les requêtes authentifiées.</p>
            </div>
        </div>

        <h1 id="authentification"
        class="sl-text-5xl sl-leading-tight sl-font-prose sl-text-heading"
    >
        Authentification
    </h1>

    <p>Gestion de l'authentification des utilisateurs via API.</p>

