        <p>Paramètres requis pour le calcul :</p>
<ul>
<li>usage_id : L'usage du véhicule (nécessaire pour trouver la table de dépréciation)</li>
<li>energy_id : La source d'énergie du véhicule (essence/diesel) pour calculer l'incidence kilométrique</li>
<li>vehicle_new_value : La valeur neuve du véhicule</li>
<li>vehicle_mileage : Le kilométrage actuel du véhicule</li>
<li>first_entry_into_circulation_date : Date de première mise en circulation (pour calculer l'âge)</li>
<li>expertise_date : Date d'expertise (pour calculer l'âge)</li>
<li>market_incidence_rate : Taux d'incidence de marché (optionnel, 0-100)</li>
</ul>
<p>Pour trouver la table de dépréciation, on utilise :</p>
<ul>
<li>L'usage (usage_id)</li>
<li>L'âge du véhicule (calculé à partir des dates first_entry_into_circulation_date et expertise_date)</li>
<li>La source d'énergie (energy_id) est utilisée pour le calcul de l'incidence kilométrique</li>
</ul>
